+            new() { Id = 13, Code = "PHYS 320", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "TTh 2:00-3:15 PM", InstructorName = "Dr. Nadia Petrov", InstructorBio = "Dr. Petrov is a theoretical physicist specializing in quantum computing foundations.", Location = "Physics Lab 301", DepartmentId = 4, DepartmentName = "Physics", IsFeatured = true },
+
