+            new() { Id = 14, Code = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from prehistory to the Renaissance.", Credits = 3, Schedule = "MWF 11:00-11:50 AM", InstructorName = "Dr. Emily Brooks", InstructorBio = "Dr. Brooks is a historian of the ancient Mediterranean and medieval Europe.", Location = "Liberal Arts 200", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
+            new() { Id = 15, Code = "HIST 201", Title = "World History II", Description = "Major events and transformations from the Enlightenment to the present day.", Credits = 3, Schedule = "TTh 9:00-10:15 AM", InstructorName = "Dr. Emily Brooks", InstructorBio = "Dr. Brooks is a historian of the ancient Mediterranean and medieval Europe.", Location = "Liberal Arts 200", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
